const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.seller_id)) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_SELLER_ID_FORMAT', message: 'seller_id must be a valid UUID.' } }];
}
if (!body.sku || !body.marketplace_id || !body.product_type || !body.attribute_name) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'sku, marketplace_id, product_type, and attribute_name are all required.'
  }}];
}

// value can now be a plain string (the original simple-attribute case,
// e.g. color) or an object of sub-fields (structured attributes, e.g.
// shirt_size's size_class/size_system/neck_size/neck_size_to) - detected
// by shape, not by a separate flag, so a caller never has to declare
// which kind it's sending.
const isStructuredInput = body.value !== null && typeof body.value === 'object' && !Array.isArray(body.value);

if (body.value === undefined || body.value === null) {
  return [{ json: {
    decision: 'REJECTED', reason: 'MISSING_VALUE',
    message: 'value is required and cannot be empty - this endpoint sets a value, it does not clear one.'
  }}];
}

if (isStructuredInput) {
  const hasAnyRealValue = Object.values(body.value).some(function(v) {
    return v !== undefined && v !== null && String(v).trim() !== '';
  });
  if (!hasAnyRealValue) {
    return [{ json: {
      decision: 'REJECTED', reason: 'MISSING_VALUE',
      message: 'value is a structured object but every field in it is empty - at least one real sub-field value is required.'
    }}];
  }
} else if (String(body.value).trim() === '') {
  return [{ json: {
    decision: 'REJECTED', reason: 'MISSING_VALUE',
    message: 'value is required and cannot be empty - this endpoint sets a value, it does not clear one.'
  }}];
}

return [{ json: {
  decision: 'VALID',
  seller_id: body.seller_id,
  sku: String(body.sku).trim(),
  marketplace_id: body.marketplace_id,
  product_type: body.product_type,
  attribute_name: body.attribute_name,
  value: isStructuredInput ? body.value : String(body.value).trim()
}}];

const sellerRows = $input.first().json;
const sellerRow = Array.isArray(sellerRows) ? sellerRows[0] : sellerRows;
const ctx = $('Validate Input').first().json;

if (!sellerRow) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_FOUND',
    seller_id: ctx.seller_id,
    message: 'No seller record exists for this seller_id.'
  }}];
}

if (sellerRow.status !== 'active') {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_ACTIVE',
    seller_id: ctx.seller_id,
    seller_status: sellerRow.status,
    message: 'This seller account is not active (status: ' + sellerRow.status + '). Access is not permitted.'
  }}];
}

return [{ json: { decision: 'ELIGIBLE' } }];

const status = $input.first().json;
  return [{ json: {
    decision: 'REJECTED',
    reason: 'RATE_LIMITED',
    current_count: status.current_count,
    window_start: status.window_start,
    message: 'This seller has made too many attribute-update requests in the current window. Please retry shortly.'
  }}];

const ctx = $('Validate Input').first().json;
const sellingPartnerRaw = $('Get Seller Selling Partner ID').first().json;
const sellingPartnerRow = Array.isArray(sellingPartnerRaw) ? sellingPartnerRaw[0] : sellingPartnerRaw;
const sellingPartnerId = sellingPartnerRow && sellingPartnerRow.selling_partner_id;
const accessToken = $('Exchange for Access Token').first().json.access_token;

if (!sellingPartnerId || !accessToken) {
  return [{ json: {
    decision: 'REJECTED', reason: 'MISSING_CREDENTIALS', sku: ctx.sku,
    message: 'Could not resolve a selling_partner_id or access_token - refusing to attempt any real calls without both.'
  }}];
}

function isRetryableStatus(err) {
  let status = null;
  if (err && err.response && typeof err.response.status === 'number') status = err.response.status;
  else if (err && err.response && typeof err.response.statusCode === 'number') status = err.response.statusCode;
  else if (err && typeof err.statusCode === 'number') status = err.statusCode;
  else {
    const match = /status code (\d{3})/i.exec((err && err.message) || '');
    if (match) status = parseInt(match[1], 10);
  }
  if (status === 404) return true;
  if (status >= 500 && status < 600) return true;
  if (!status) return true;
  return false;
}

const isStructured = ctx.value !== null && typeof ctx.value === 'object' && !Array.isArray(ctx.value);

const result = {
  sku: ctx.sku,
  attribute_name: ctx.attribute_name,
  patch_status: null,
  patch_issues: [],
  verified: false,
  verify_issues: [],
  verify_attempts: 0,
  real_value: null,
  error: null
};

try {
  // Structured: send the sub-fields directly, matching the real shape
  // confirmed on live listings (shirt_size's own entries have
  // size_class/size_system/etc. as direct keys, not wrapped in a
  // `value` field). Simple: unchanged from before.
  const attributeValue = isStructured
    ? Object.assign({}, ctx.value, { marketplace_id: ctx.marketplace_id })
    : { value: ctx.value, marketplace_id: ctx.marketplace_id };

  const patchResponse = await this.helpers.httpRequest({
    method: 'PATCH',
    url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(ctx.sku),
    qs: { marketplaceIds: ctx.marketplace_id, issueLocale: 'en_US' },
    headers: { 'Content-Type': 'application/json', 'x-amz-access-token': accessToken },
    body: {
      productType: ctx.product_type,
      patches: [{ op: 'replace', path: '/attributes/' + ctx.attribute_name, value: [attributeValue] }]
    },
    json: true
  });
  result.patch_status = patchResponse.status || null;
  result.patch_issues = patchResponse.issues || [];
} catch (err) {
  result.error = 'patch call failed: ' + (err.message || String(err));
  return [{ json: { decision: 'SUMMARIZED', result: result } }];
}

const hasHardError = result.patch_status === 'INVALID'
  || result.patch_issues.some(function(i) { return i.severity === 'ERROR'; });

if (hasHardError) {
  return [{ json: { decision: 'SUMMARIZED', result: result } }];
}

const verifyDelaysMs = [5000, 10000, 15000, 20000, 30000];

for (let i = 0; i <= verifyDelaysMs.length; i++) {
  if (i > 0) {
    await new Promise(function(resolve) { setTimeout(resolve, verifyDelaysMs[i - 1]); });
  }
  result.verify_attempts++;
  try {
    const stateResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(ctx.sku),
      qs: { marketplaceIds: ctx.marketplace_id, includedData: 'attributes,issues' },
      headers: { 'x-amz-access-token': accessToken },
      json: true
    });
    const attrs = stateResponse.attributes || {};
    const entries = attrs[ctx.attribute_name];
    const currentEntry = (Array.isArray(entries) && entries[0]) ? entries[0] : null;
    result.verify_issues = stateResponse.issues || [];

    if (isStructured) {
      result.real_value = currentEntry;
      if (currentEntry) {
        // Verified once every field actually sent matches what Amazon
        // now reports - case-insensitive, trimmed, same deliberately
        // lenient comparison as the simple case, for the same reason
        // (a real success shouldn't read as a false failure over
        // casing or whitespace). A field the caller didn't send at all
        // is never checked - only what was actually part of this update.
        const allSentFieldsMatch = Object.keys(ctx.value).every(function(key) {
          const sentVal = ctx.value[key];
          if (sentVal === undefined || sentVal === null || String(sentVal).trim() === '') return true;
          const realVal = currentEntry[key];
          return realVal !== undefined && realVal !== null
            && String(realVal).trim().toLowerCase() === String(sentVal).trim().toLowerCase();
        });
        if (allSentFieldsMatch) {
          result.verified = true;
          result.error = null;
          break;
        }
      }
    } else {
      const currentValue = (currentEntry && currentEntry.value !== undefined) ? String(currentEntry.value) : null;
      result.real_value = currentValue;
      if (currentValue !== null && currentValue.trim().toLowerCase() === String(ctx.value).trim().toLowerCase()) {
        result.verified = true;
        result.error = null;
        break;
      }
    }
  } catch (err) {
    const message = 'verify call failed: ' + (err.message || String(err));
    result.error = message;
    if (isRetryableStatus(err) && i < verifyDelaysMs.length) {
      continue;
    }
    break;
  }
}

return [{ json: {
  decision: 'SUMMARIZED',
  result: result
}}];
